from pathlib import Path
import json,collections,statistics
for p in sorted(Path('validation_data').glob('*.jsonl'),key=lambda p:int(p.stem)):
 rows=[json.loads(l) for l in p.open()]; errs=collections.Counter(); empty=0; ex=[]
 for i,d in enumerate(rows):
  f=d.get('fail_debug')
  if f:
   err=f.get('error'); typ='wrong_answer' if not err else str(err).split('(')[0][:110]
   errs[typ]+=1
   if f.get('output') in [None,'[]','',[]]: empty+=1
   if p.stem=='45' and len(ex)<12: ex.append((i,d['pass_rate'],f))
 print('VAL',p.stem,'acc',sum(d['acc'] for d in rows),'pass_rate',round(statistics.mean(d['pass_rate'] for d in rows),4),'fail_types',dict(errs),'empty_outputs',empty)
 if p.stem=='45':
  for i,rate,f in ex: print('EX',i,rate,json.dumps(f,ensure_ascii=False)[:2000])
print('TRAIN')
allgroups=[]; allrows=[]
for p in sorted(Path('rollout_data').glob('*.jsonl'),key=lambda p:int(p.stem)):
 rows=[json.loads(l) for l in p.open()]; groups=collections.defaultdict(list)
 for d in rows: groups[d['input']].append(d)
 allrows+=rows; allgroups+=list(groups.values())
 mixed=sum(len({d['score'] for d in g})>1 for g in groups.values())
 if int(p.stem) in [1,2,5,10,15,20,25,30,35,40,45,49]: print(p.stem,'reward',round(statistics.mean(d['score'] for d in rows),5),'partial',round(statistics.mean(d['pass_rate'] for d in rows),5),'groups',len(groups),'mixed',mixed,'group_counts',dict(collections.Counter(len(g) for g in groups.values())))
print('ALL groups',len(allgroups),'binary distribution',dict(collections.Counter(int(sum(d['score'] for d in g)) for g in allgroups)))
print('ALL score',statistics.mean(d['score'] for d in allrows),'partial',statistics.mean(d['pass_rate'] for d in allrows),'partial_unrewarded',sum(0<d['pass_rate']<1 and d['score']==0 for d in allrows),'rows',len(allrows))
for a,b in [(1,10),(11,20),(21,30),(31,40),(41,49)]:
 rs=[d for d in allrows if a<=d['step']<=b]; print('WINDOW',a,b,len(rs),statistics.mean(d['score'] for d in rs),statistics.mean(d['pass_rate'] for d in rs),statistics.mean(len(d['output']) for d in rs))
PY","max_output_tokens":7000}));

