from pathlib import Path
import json,collections,re,statistics
for sn in ['0','45']:
 rows=[json.loads(l) for l in Path('validation_data',sn+'.jsonl').open()]
 print('STEP',sn)
 classes=collections.defaultdict(list)
 for i,d in enumerate(rows):
  f=d.get('fail_debug'); out=d['output']
  if not f: continue
  if re.search(r'''if\s+__name__\s*==\s*["']__main__["']''',out): classes['main_guard'].append(i)
  if f.get('output')=='[]' and not f.get('error'): classes['silent'].append(i)
  if f.get('error') and 'NameError' in str(f.get('error')): classes['name_error'].append(i)
