import pyarrow.parquet as pq, json,collections, math
from pathlib import Path
# Count contradictory single-word labels, excluding numerically equivalent formatting.
rows=pq.read_table('taco_verl/train.parquet').to_pylist(); bad={}; cases=[]
for d in rows:
 gt=json.loads(d['reward_model']['ground_truth']);by=collections.defaultdict(set)
 for x,y in zip(gt['inputs'],gt['outputs']):
  if isinstance(x,list):x='\n'.join(x)
  if isinstance(y,list):y='\n'.join(y)
  if isinstance(x,str) and isinstance(y,str):by[x].add(y.strip())
 for x,ys in by.items():
  if len(ys)<2 or not all(len(y.split())==1 for y in ys):continue
  try:
   nums=list(map(float,ys));lo=min(nums);hi=max(nums)
   numeric_equiv=math.isclose(lo,hi,rel_tol=1e-5,abs_tol=1e-8) or all(round(v,3)==round(nums[0],3) for v in nums)
  except ValueError:numeric_equiv=False
  if not numeric_equiv:
   bad[d['prompt'][0]['content']]=d['extra_info']['problem_id']; cases.append((d['extra_info']['problem_id'],x,ys));break
print('NON_EQ_SINGLE_TOKEN_CONFLICT_PROBLEMS',len(bad))
hits=collections.defaultdict(list)
for p in sorted(Path('rollout_data').glob('*.jsonl'),key=lambda p:int(p.stem)):
 for d in map(json.loads,p.read_text().splitlines()):
  prompt=d['input'].removeprefix('user\n').removesuffix('\nassistant\n')
  if prompt in bad:hits[bad[prompt]].append(d)
print('OBSERVED',len(hits),'groups',sum(len(v)//8 for v in hits.values()),'rows',sum(len(v) for v in hits.values()),'all_zero',all(d['score']==0 for v in hits.values() for d in v))
print('CONFLICT_EXAMPLES',[(pid,repr(x)[:90],sorted(y)) for pid,x,y in cases if pid not in ['train9023','train13807']][:10])
print('OPTIMIZER_CONTEXT')
